c:
\begin{equation}
\label{rg:scales}
 D\ge2^{64},\quad 1\le U\le\sqrt D,\quad
 A_1\asymp H=D^{3/4},\quad X=D^{3/8},\quad
 V=X^{1/6}/2 .
\end{equation}

\begin{equation}
\label{rg:profile}
 \begin{aligned}
 B_W&=\|W\|_\infty,\qquad
 \widehat W(t)=\int_0^\infty W(x)x^{-it}\,\frac{dx}{x},\\
 \mathcal M(W)&=\frac1{2\pi}\int_{\mathbb R}|\widehat W(t)|\,dt,
 &V_1(W)&=B_W+\int_1^2|W'(x)|\,dx .
 \end{aligned}
\end{equation}

\begin{equation}
\label{rg:frequency-set}
 \mathcal T_X=\left\{(\mathfrak w,\mathfrak s):
 \begin{array}{l}
 \mathfrak w\text{ integral},\ N\mathfrak w<64,\quad
 \mathfrak s\text{ good integral},\\
 V<N\mathfrak s\le2V,\quad
 N\mathfrak w(N\mathfrak s)^6\le X
 \end{array}\right\}.
\end{equation}

\begin{equation}
\label{rg:exact-prefix}
 \begin{split}
 \mathcal P_X[A_U,A_U]
 ={}&\frac{A_1}{D}\sum_\Omega
 h_{AB\rho}(\mathcal O)c_U(\mathfrak m)\overline{c_U(\mathfrak n)}
          \frac{\varepsilon(\eta_\Omega)}{\sqrt{F_\Omega}}\\
 &\ \cdot\sum_{\mathfrak e\mid P_S}
          \frac{\mu(\mathfrak e)\eta_\Omega(\mathfrak e)}{N\mathfrak e}
 \sum_{\substack{\mathfrak k\ {\mathrm{good},SF}\\
                      N\mathfrak k\le K_{\mathrm{cut}}}}
          \frac{\mu(\mathfrak k)\eta_\Omega(\mathfrak k)^2}
                          {(N\mathfrak k)^2}\\
 &\ \cdot\sum_{(\mathfrak w,\mathfrak s)\in\mathcal T_X}
 \overline{\eta_\Omega(\mathfrak w)}\,\overline{\rho(\mathfrak s)}^{\,6}
       \mathbf1_{(\mathfrak s,\mathfrak q)=1}
 \dot G\left(\frac{A_1N\mathfrak w(N\mathfrak s)^6}
                  {(N\mathfrak k)^2N\mathfrak e F_\Omega}\right).
 \end{split}
\end{equation}

\begin{equation}
\label{rg:source-gauss}
 G_{\mathfrak a}^{\mathrm{src}}
 =\frac1{\sqrt{N\mathfrak a}}\sum_{x\bmod\alpha_{\mathfrak a}}
 \chi_{3,\mathfrak a}(x)
             e^{2\pi i\operatorname{Tr}(x/\alpha_{\mathfrak a})}.
\end{equation}

\begin{equation}
\label{rg:normalizations}
 \begin{aligned}
 \Theta_\ell(\mathfrak a)&=
       (\alpha_{\mathfrak a}/|\alpha_{\mathfrak a}|)^\ell,\\
 \vartheta(\mathfrak a)
       &=\Theta_1(\mathfrak a)
                    \overline{\chi_{3,\mathfrak a}(2)},\\
 G_{\mathfrak a}^{\mathrm{act}}
       &=\chi_{3,\mathfrak a}(\lambda)G_{\mathfrak a}^{\mathrm{src}}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{rg:row-definition}
 \mathcal F_\psi(T;\mathfrak t;Q,I)
 =\sum_{\substack{\mathfrak a\ {\mathrm{good},SF}\\
                 N\mathfrak a\in I,\;(\mathfrak a,Q)=1}}
 \psi(\mathfrak a)\overline{G_{\mathfrak a}^{\mathrm{act}}}
 \chi_{3,\mathfrak a}(\alpha_{\mathfrak t})
                     \frac{W(N\mathfrak a/T)}{\sqrt{N\mathfrak a}} .
\end{equation}

\begin{equation}
\label{rg:sharp-bound}
 |\mathcal F_\psi(T;\mathfrak t;1,I)|
 \ll_{\mathrm{fixed},\epsilon} V_1(W)(2+T N\mathfrak t)^\epsilon
       \min\{\sqrt T,\ T^{1/4}(N\mathfrak t)^{3/8}\},
 \qquad T\ge1 .
\end{equation}

\begin{equation}
\label{rg:opened}
 B_U(\mathfrak m):=\mu(\mathfrak m)A_U(\mathfrak m)
 =\sum_{\substack{\mathfrak a\mathfrak b\mathfrak c=\mathfrak m\\
                   N\mathfrak a,N\mathfrak b\le U}}\mu(\mathfrak c).
\end{equation}

\begin{equation}
\label{rg:small-prefix-weight}
 \frac{1}{\sqrt{N\mathfrak pN\mathfrak h}}
 \left(\frac D{N\mathfrak pN\mathfrak h}\right)^{1/4}
 \bigl(N(\mathfrak p\mathfrak k\mathfrak h)\bigr)^{3/8}
 =D^{1/4}(N\mathfrak k)^{3/8}
       (N\mathfrak p)^{-3/8}(N\mathfrak h)^{-3/8}.
\end{equation}

\begin{equation}
\label{rg:joint-selector}
 \begin{aligned}
 f(x,y)&=\sum_{\chi,\psi\in\widehat{\mathcal H}}
                           b_{\chi,\psi}\chi(x)\psi(y),\\
 b_{\chi,\psi}
   &=|\mathcal H|^{-2}\sum_{x,y\in\mathcal H}
                   f(x,y)\overline{\chi(x)\psi(y)},\\
 \sum_{\chi,\psi}|b_{\chi,\psi}|
   &\le|\mathcal H|\,\|f\|_\infty .
 \end{aligned}
\end{equation}

\begin{equation}
\label{rg:gauss-cross}
 \overline{G_{\mathfrak u\mathfrak v}^{\mathrm{act}}}
 =\overline{G_{\mathfrak u}^{\mathrm{act}}}\,
  \overline{G_{\mathfrak v}^{\mathrm{act}}}\,
                    \chi_{3,\mathfrak u}(\alpha_{\mathfrak v}).
\end{equation}

\begin{equation}
\label{rg:cubic-input}
 \bigl\|[\chi_{3,\mathfrak u}(\alpha_{\mathfrak v})]
                            _{N\mathfrak u\asymp P,\,
                              N\mathfrak v\asymp L}\bigr\|_{\mathrm{op}}
 \ll_\epsilon(PL)^\epsilon
                  \sqrt{P+L+(PL)^{2/3}} .
\end{equation}

W(N\mathfrak uN\mathfrak v/D)
 =\frac1{2\pi}\int_{\mathbb R}\widehat W(t)D^{-it}
                       (N\mathfrak u)^{it}(N\mathfrak v)^{it}\,dt .

\begin{equation}
\label{rg:prefix-mask}
 \mathbf1_{(\mathfrak p\mathfrak v,\mathfrak n)=1}
 =\mathbf1_{(\mathfrak p,\mathfrak n)=1}
                 \mathbf1_{(\mathfrak v,\mathfrak n)=1}.
\end{equation}

\begin{equation}
\label{rg:deletion-identity}
 \begin{split}
 \mathcal F_\psi(T;\mathfrak t;Q,I)
 =\sum_{\substack{\mathfrak h\mid Q\\(\mathfrak h,\mathfrak t)=1}}
 &\frac{\mu(\mathfrak h)\psi(\mathfrak h)
       \overline{G_{\mathfrak h}^{\mathrm{act}}}
       \chi_{3,\mathfrak h}(\alpha_{\mathfrak t})}
                 {\sqrt{N\mathfrak h}}\\
 &\cdot\mathcal F_\psi(T/N\mathfrak h;
                              \mathfrak h\mathfrak t;1,I/N\mathfrak h).
 \end{split}
\end{equation}
